/**
 * 负责奇迹商人从实际库存选择赠予。输入为当前原体和已验证的技能／收货选择；
 * 阵营只晚查实际值，同值组件替换不增加引用撤权；已付反噬仍使用原 owner 谓词。
 * 输出为实际拥有的赠予、反噬提案和跳过／提交事实。已付提案保留原生命资格，不转给替换赠予者。
 */
import { closeMerchantTrade, recordMerchantTrade } from "./state";

import type { MiracleSkill } from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { canMerchantTrade, getMerchantState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasMerchantNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

export const MIRACLE_MERCHANT_STAGE: NightStageHandler = {
  id: "miracle_merchant",
  priority: 125,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.MiracleMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getMerchantState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = () =>
        ctx.isCurrent() &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.MiracleMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getMerchantState(role) === state &&
        livingNightLife(ctx.world, life);
      const current = () => ownerCurrent() && canMerchantTrade(state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["bestow_ability"], {
                stage: "miracle_merchant",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          closeMerchantTrade(state, day);
          recordCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "merchant_trade_skipped",
            payload: { actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "bestow_ability") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "bestow_ability") continue;
        const { target_id: targetId, skill } = valid.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        const failure = target.camp === Camp.Wolf;
        if (!failure) {
          const base = {
            id: "gift:miracle",
            activation: "lucky" as const,
            source: { kind: "gift" as const, actorId },
            sourceDisclosed: false,
            startsOnDay: day,
            maxUses: 1,
          };
          if (skill === "check")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "seer_check",
                state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
              },
              ctx.events,
            );
          if (skill === "guard")
            grantNightAbility(
              ctx.world,
              targetId,
              { ...base, kind: "guard", state: { lastTarget: null } },
              ctx.events,
            );
          if (skill === "poison")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "potion",
                state: {
                  heal: 0,
                  poison: 1,
                  selfHealRule: WitchSelfHealRule.Disabled,
                  canSelfHeal: false,
                  healUsedThisNight: false,
                  poisonUsedThisNight: false,
                },
              },
              ctx.events,
            );
        }
        recordMerchantTrade(state, day, targetId, skill as MiracleSkill);
        recordCommit(ctx.world, day);
        if (failure)
          (ctx.state.merchantBacklashes ??= []).push({ target: life, isCurrent: ownerCurrent });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failure ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("merchant_valid_action_missing");
    }
  },
};

/**
 * 负责 奇迹商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getMerchantState,
  freshMerchantState,
  setMerchantState,
  projectMerchantState,
  canMerchantTrade,
} from "./state";
import { MIRACLE_MERCHANT_STAGE } from "./night_stage";
import { LUCKY_ABILITY_STAGE } from "./lucky_stage";

export const MIRACLE_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.MiracleMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("miracle_merchant"),
    skillBrief: text("zh-CN", "role.miracle_merchant.brief"),
    supportedBoardRoles: [
      Role.CursedFox,
      Role.MiracleMerchant,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Dreamer,
      Role.Villager,
    ],
  },
  runtime: {
    init: (role) => {
      if (!getMerchantState(role)) setMerchantState(role, freshMerchantState());
    },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [MIRACLE_MERCHANT_STAGE, LUCKY_ABILITY_STAGE],
    possibleNightAbilities: ["seer_check", "potion", "guard"],
    toolSpecs: [
      {
        name: "bestow_ability",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: "integer" },
            skill: { type: "string", enum: ["check", "poison", "guard"] },
          },
          required: ["target_id", "skill"],
          additionalProperties: false,
        },
        argHint: 'bestow_ability args: {"target_id":number,"skill":"check"|"poison"|"guard"}',
        userPromptHintKey: "action.bestow_ability.hint",
      },
    ],
    validationRules: {
      bestow_ability: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getMerchantState(role);
        if (
          role.role !== Role.MiracleMerchant ||
          world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canMerchantTrade(state, day)
        )
          return { code: RuleError.MerchantUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "bestow_ability") return { code: RuleError.ToolMismatch };
        if (!["check", "poison", "guard"].includes(toolCall.args.skill))
          return { code: RuleError.MerchantSkill };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.MerchantTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        bestow_ability: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, skill: args.skill };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("bestow_ability")) return null;
      const target = pick();
      return target === null
        ? null
        : { name: "bestow_ability", args: { target_id: target, skill: "check" } };
    },
  },
  presentation: nativeRolePresentation("miracle_merchant"),
};

/**
 * 负责奇迹商人的复制安装、原槽读取、交易记录与玩家投影。输入为原角色、状态及夜间日次；
 * 输出保留选择、库存和等待资格，公开 DTO 类型归公共契约。
 * 只写所属 miracle_merchant 槽及交易字段，保持复制后安装与原字段失败顺序；
 * 不提供通用私有状态写口，不刷新库存、退款或创建行动许可。
 */
import type {
  MiracleSkill,
  MerchantState,
  MerchantReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerMerchantState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { copyAbilityData } from "../abilities";

export const freshMerchantState = (): MerchantState => ({
  remaining: 1,
  closedDay: null,
  choice: null,
});
export function getMerchantState(role: RoleComponent | undefined): MerchantReadState | undefined {
  return (role as { readonly privateState: { readonly miracle_merchant?: unknown } } | undefined)
    ?.privateState.miracle_merchant as MerchantReadState | undefined;
}
export function setMerchantState(role: RoleComponent, state: MerchantState): void {
  (role.privateState as { miracle_merchant: MerchantState }).miracle_merchant =
    copyAbilityData(state);
}
export function projectMerchantState(state: MerchantReadState): PlayerMerchantState {
  return {
    remaining: state.remaining,
    closedDay: state.closedDay,
    choice: state.choice
      ? { day: state.choice.day, targetId: state.choice.targetId, skill: state.choice.skill }
      : null,
  };
}
export function canMerchantTrade(state: MerchantReadState, day: number): boolean {
  return state.remaining > 0 && day >= 1 && (state.closedDay === null || state.closedDay < day);
}

/** 调用方保留原等待、当前性与提交边界；这里只关闭当日机会，不消费交易库存。 */
export function closeMerchantTrade(state: MerchantReadState, day: number): void {
  (state as { closedDay: number | null }).closedDay = day;
}
/** 已付交易依次写库存、关窗日和选择对象；失败保留先完成的字段，不回滚或补发通知。 */
export function recordMerchantTrade(
  state: MerchantReadState,
  day: number,
  targetId: number,
  skill: MiracleSkill,
): void {
  (state as { remaining: 0 | 1 }).remaining = 0;
  (state as { closedDay: number | null }).closedDay = day;
  (state as { choice: MerchantState["choice"] }).choice = {
    day,
    targetId,
    skill: skill as MiracleSkill,
  };
}

/**
 * 负责黑市商人在后置受赠行动之前的交易阶段。输入为当前商人库存与已验证的技能／收货选择；
 * 阵营在原捕获／复验点取真实 Camp 值；已付反噬 owner 保原谓词，不混入新执行退休。
 * 输出为独立受赠能力或赠枪、反噬提案和跳过／提交事实。已付效果仍绑定原生命，不转给替换商人。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day);
      if (!current()) continue;
      const skip = () => {
        closeBlackMarketTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["black_market_trade"], {
                stage: "black_market_merchant",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        if (!failed) {
          if (skill === "gun") grantDeathGun(ctx.world, actorId, targetId, day, ctx.events);
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check")
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "seer_check",
                  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                },
                ctx.events,
              );
            else
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "potion",
                  state: {
                    heal: 0,
                    poison: 1,
                    selfHealRule: WitchSelfHealRule.Disabled,
                    canSelfHeal: false,
                    healUsedThisNight: false,
                    poisonUsedThisNight: false,
                  },
                },
                ctx.events,
              );
          }
        }
        recordBlackMarketTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};

/**
 * 负责 黑市商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getBlackMarketState,
  freshBlackMarketState,
  setBlackMarketState,
  projectBlackMarketState,
  canBlackMarketTrade,
} from "./state";
import { BLACK_MARKET_TRADE_STAGE, BLACK_MARKET_RECIPIENT_STAGE } from "./night_stage";
export const BLACK_MARKET_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.BlackMarketMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("black_market_merchant"),
    skillBrief: text("zh-CN", "role.black_market_merchant.brief"),
    supportedBoardRoles: [
      Role.BlackMarketMerchant,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Dreamer,
      Role.Villager,
    ],
  },
  runtime: {
    init: (role) => {
      if (!getBlackMarketState(role)) setBlackMarketState(role, freshBlackMarketState());
    },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [BLACK_MARKET_TRADE_STAGE, BLACK_MARKET_RECIPIENT_STAGE],
    possibleNightAbilities: ["seer_check", "potion"],
    possibleDeathAbilities: ["gun"],
    toolSpecs: [
      {
        name: "black_market_trade",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: "integer", minimum: 1 },
            skill: { type: "string", enum: ["check", "poison", "gun"] },
          },
          required: ["target_id", "skill"],
          additionalProperties: false,
        },
        argHint: 'black_market_trade args: {"target_id":number,"skill":"check"|"poison"|"gun"}',
        userPromptHintKey: "action.black_market_trade.hint",
      },
    ],
    validationRules: {
      black_market_trade: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getBlackMarketState(role);
        if (
          role.role !== Role.BlackMarketMerchant ||
          world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canBlackMarketTrade(state, day)
        )
          return { code: RuleError.MerchantUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "black_market_trade") return { code: RuleError.ToolMismatch };
        if (!["check", "poison", "gun"].includes(toolCall.args.skill))
          return { code: RuleError.BlackMarketSkill };
        if (
          !Number.isSafeInteger(toolCall.args.target_id) ||
          toolCall.args.target_id === actorId ||
          !isAliveTarget(world, toolCall.args.target_id)
        )
          return { code: RuleError.MerchantTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        black_market_trade: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, skill: args.skill };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("black_market_trade")) return null;
      const target = pick();
      return target === null
        ? null
        : { name: "black_market_trade", args: { target_id: target, skill: "check" } };
    },
  },
  presentation: nativeRolePresentation("black_market_merchant"),
};

/**
 * 负责黑市商人的状态安装、原槽读取、交易记录与玩家投影。输入为原角色、状态和交易日次；
 * 输出为复制安装后的状态、原只读引用或裁剪数据，实际类型归公共玩家视图契约。
 * 本模块只写所属 black_market_merchant 槽及交易字段，不替换角色容器、退款或创建行动许可。
 * 次数、关窗日和选择按原顺序提交；复制或字段写入失败保留此前已经完成的前缀。
 */
import type {
  BlackMarketSkill,
  BlackMarketState,
  BlackMarketReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerBlackMarketState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { copyAbilityData } from "../abilities";

export const freshBlackMarketState = (): BlackMarketState => ({
  remaining: 1,
  closedDay: null,
  choice: null,
});
export function getBlackMarketState(
  role: RoleComponent | undefined,
): BlackMarketReadState | undefined {
  return (
    role as { readonly privateState: { readonly black_market_merchant?: unknown } } | undefined
  )?.privateState.black_market_merchant as BlackMarketReadState | undefined;
}
export function setBlackMarketState(role: RoleComponent, state: BlackMarketState): void {
  (role.privateState as { black_market_merchant: BlackMarketState }).black_market_merchant =
    copyAbilityData(state);
}
export function projectBlackMarketState(state: BlackMarketReadState): PlayerBlackMarketState {
  return {
    remaining: state.remaining,
    closedDay: state.closedDay,
    choice: state.choice
      ? { day: state.choice.day, targetId: state.choice.targetId, skill: state.choice.skill }
      : null,
  };
}
export function canBlackMarketTrade(state: BlackMarketReadState, day: number): boolean {
  return state.remaining === 1 && day >= 1 && (state.closedDay === null || state.closedDay < day);
}

/** 调用方保留原等待、当前性与提交边界；这里只关闭当日机会，不消费交易库存。 */
export function closeBlackMarketTrade(state: BlackMarketReadState, day: number): void {
  (state as { closedDay: number | null }).closedDay = day;
}
/** 已付交易依次写库存、关窗日和选择对象；失败保留先完成的字段，不回滚或补发通知。 */
export function recordBlackMarketTrade(
  state: BlackMarketReadState,
  day: number,
  targetId: number,
  skill: BlackMarketSkill,
): void {
  (state as { remaining: 0 | 1 }).remaining = 0;
  (state as { closedDay: number | null }).closedDay = day;
  (state as { choice: BlackMarketState["choice"] }).choice = { day, targetId, skill };
}
